"""Routes for Files, generated by Dryv; the engine implements ExploreFilesService."""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Awaitable, Callable
from typing import Annotated

from fastapi import APIRouter, Body, Depends, Query, Request

from mzizi_engine.api.schemas.api.explore.models.file_view import FileView
from mzizi_engine.api.schemas.api.explore.models.listing import Listing
from mzizi_engine.api.schemas.api.explore.models.raw_file import RawFile
from mzizi_engine.api.schemas.api.explore.models.root_list import RootList
from mzizi_engine.api.schemas.api.explore.models.save_file_body import SaveFileBody
from mzizi_engine.api.schemas.api.explore.models.save_file_result import SaveFileResult

__all__ = ["ExploreFilesService", "build_explore_files_router"]

type Guard = Callable[[Request], Awaitable[None]]
"""An async FastAPI dependency that raises 401 or 403 before the route runs."""


class ExploreFilesService(ABC):
    """What Files needs from handwritten code. Raise ``fastapi.HTTPException`` for failures."""

    @abstractmethod
    async def get_file(self, *, root: str, path: str, offset: int | None, limit: int | None) -> FileView:
        """One file viewed by kind: text, CSV rows, parsed JSON or YAML."""

    @abstractmethod
    async def get_raw_file(self, *, root: str, path: str | None) -> RawFile:
        """The bytes of one file (up to 16 MB) for preview and download, as base64 with its content type."""

    @abstractmethod
    async def list_file_roots(self) -> RootList:
        """The folders the explorer may show."""

    @abstractmethod
    async def list_files(self, *, root: str, path: str | None) -> Listing:
        """A folder's entries; a file path lists the folder that holds it."""

    @abstractmethod
    async def save_file(self, *, body: SaveFileBody) -> SaveFileResult:
        """Save a text file under the dev root (never outside it)."""


def build_explore_files_router(service: ExploreFilesService, guard: Guard | None = None) -> APIRouter:
    """Routes for Files, delegating to ``service``; ``guard`` protects every route."""

    router = APIRouter(tags=["Files"], dependencies=[Depends(guard)] if guard else [])

    @router.get(
        "/v1/explore/file",
        response_model=FileView,
        status_code=200,
        summary="One file viewed by kind: text, CSV rows, parsed JSON or YAML.",
    )
    async def get_file(
        root: Annotated[str, Query(alias="root")],
        path: Annotated[str, Query(alias="path")],
        offset: Annotated[int | None, Query(alias="offset")] = None,
        limit: Annotated[int | None, Query(alias="limit")] = None,
    ) -> FileView:
        return await service.get_file(root=root, path=path, offset=offset, limit=limit)

    @router.get(
        "/v1/explore/file/data",
        response_model=RawFile,
        status_code=200,
        summary="The bytes of one file (up to 16 MB) for preview and download, as base64 with its content type.",
    )
    async def get_raw_file(
        root: Annotated[str, Query(alias="root")],
        path: Annotated[str | None, Query(alias="path")] = None,
    ) -> RawFile:
        return await service.get_raw_file(root=root, path=path)

    @router.get(
        "/v1/explore/roots",
        response_model=RootList,
        status_code=200,
        summary="The folders the explorer may show.",
    )
    async def list_file_roots() -> RootList:
        return await service.list_file_roots()

    @router.get(
        "/v1/explore/files",
        response_model=Listing,
        status_code=200,
        summary="A folder\u0027s entries; a file path lists the folder that holds it.",
    )
    async def list_files(
        root: Annotated[str, Query(alias="root")],
        path: Annotated[str | None, Query(alias="path")] = None,
    ) -> Listing:
        return await service.list_files(root=root, path=path)

    @router.put(
        "/v1/explore/file",
        response_model=SaveFileResult,
        status_code=200,
        summary="Save a text file under the dev root (never outside it).",
    )
    async def save_file(
        body: Annotated[SaveFileBody, Body()],
    ) -> SaveFileResult:
        return await service.save_file(body=body)

    return router
